recs = []
for row in W:
    lemma, pos, gender, en, vi, topic, de, xen, xvi, pool_pos = row[:10]
    rec = {"lemma": lemma, "partOfSpeech": pos}
    if pool_pos: rec["poolPos"] = pool_pos
    if len(row) > 10: rec["surface"] = row[10]
    if gender: rec["gender"] = gender
    rec.update({"glossEn": en, "glossVi": vi, "topic": topic, "examples": [{"target": de, "en": xen, "vi": xvi}]})
    recs.append(rec)
assert len({r["lemma"] for r in recs}) == len(recs), "duplicate lemma"
S = pathlib.Path(r"C:\Users\MSI\AppData\Local\Temp\claude\C--Users-MSI-Documents-app-hoc-ngoai-ngu\82ea6b33-e22d-4a2d-907b-9b4441f9e202\scratchpad")
pathlib.Path(r"C:\src\lft\content\de\_drafts\lexicon-add\OUTPUT.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in recs), encoding="utf-8")
allp = S / "de-lexicon-add-all.jsonl"
old = [json.loads(l) for l in allp.read_text(encoding="utf-8").splitlines() if l.strip()]
have = {r["lemma"] for r in old}
allp.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in old + [r for r in recs if r["lemma"] not in have]), encoding="utf-8")
print(len(recs), "records")
